ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"query": {
    "aggregate": p('mongo-db-sapi.collections.client'),
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": {
        	"Numero_Identificacion": vars.requestOrder.customer.documentNumber,
        	"Tipo_Documento": vars.requestOrder.customer.documentType
        }
      }
    ],
    "cursor": {}
  }
}

%dw 2.0 output application/json
import modules::GlobalFunctions as global
var record = vars.responseMongo.result[0]
// Wrapper común: empaqueta el resultado de cualquier validación fun resultado(id: String, condicionValida: Boolean, mensajeValido: String, mensajeInvalido: String) = { evaluateId: id, isValid: condicionValida, detail: if (condicionValida) mensajeValido else mensajeInvalido }
--- [
// 3. EnvioComunicaciones: Medio y Dato poblados resultado("Campo_EnvioComunicaciones", (record.EnvioComunicaciones != null) and global::poblado(record.EnvioComunicaciones.MedioComunicacion) or global::poblado(record.EnvioComunicaciones.DatoComunicacion1), "EnvioComunicaciones con Medio y Dato poblados", "EnvioComunicaciones ausente o incompleto"),
// 4. Correo_Electronico O Telefono_Movil poblado resultado("Campo_ContactoDirecto", global::poblado(record.Correo_Electronico) or global::poblado(record.Telefono_Movil), "Correo o Telefono_Movil poblado", "Correo y Telefono_Movil vacios"),
// 5. Datos demograficos: Pais, Ciudad, Departamento poblados resultado("Campo_DatosDemograficos", global::poblado(record.Pais) and global::poblado(record.Ciudad) and global::poblado(record.Departamento), "Pais, Ciudad y Departamento poblados", "Falta al menos un dato demografico (Pais/Ciudad/Departamento)") ]

%dw 2.0
output application/json
---
{
	ruleId: p('rules-id.data-client'),
	isValid: false,
	detailEvaluated: [
		{
	    "evaluateId": "Cliente_Inexistente",
	    "isValid": false,
	    "detail": "Cliente no existe o esta Inactivo"
  		}
	]
}
